  function edgeHit(p){if(editorInput||G.roots(scene()).length>1||G.selectedSurfaces(scene()).length>1)return null;const points=selectionOutline(),z=view().zoom;if(!points)return null;for(const h of handles(points))if(Math.hypot(h.x-p.x,h.y-p.y)<8/z)return h.edge;for(let i=0;i<4;i++){const a=points[i],b=points[(i+1)%4],length=(b.x-a.x)**2+(b.y-a.y)**2,t=Math.max(0,Math.min(1,((p.x-a.x)*(b.x-a.x)+(p.y-a.y)*(b.y-a.y))/length));if(Math.hypot(p.x-a.x-t*(b.x-a.x),p.y-a.y-t*(b.y-a.y))<5/z)return ['n','e','s','w'][i];}return null;}
