      const component=!!g.components[f.id],entry=cached(f);ctx.fillStyle='#b2bbca';ctx.font=12/v.zoom+'px system-ui';ctx.textAlign='left';ctx.fillText((component?'◇ ':'▣ ')+f.name,f.x,f.y-13/v.zoom);
